11	/** Express RequestHandler tagged with the original transport-agnostic Handler. */
12	export type TaggedHandler = RequestHandler & { __handler: Handler };
13	
14	/**
15	 * Wraps a transport-agnostic {@link Handler} as an Express {@link RequestHandler}.
16	 *
17	 * Bridging notes:
18	 * - `req.body` is already parsed by express.json(); json() returns it directly
19	 *   so the raw body is never re-parsed.
20	 * - Path params come from `req.params`, query params from `req.query`.
21	 * - `req.actor.type === "none"` is normalised to `null` so handlers can do a
22	 *   simple null-check rather than inspecting the string.
23	 * - The Web API `Response` returned by the handler is forwarded to Express `res`
24	 *   by copying status, headers, and body.
25	 * - The returned wrapper is tagged with `__handler` pointing to the original
26	 *   `Handler` so Cloudflare Workers can extract it via the express-router-bridge.
27	 */
28	export function expressHandler(handler: Handler, deps: AdapterDeps): TaggedHandler {
29	  const wrapper = async (req: Request, res: Response, next: NextFunction) => {
30	    try {
31	      // Build the base URL from the incoming request. Express provides
32	      // req.hostname and req.originalUrl which together give us a fully-formed
33	      // URL object without needing the raw Host header gymnastics.
34	      const protocol = (req as { protocol?: string }).protocol ?? "http";
35	      const baseUrl = `${protocol}://${req.hostname}`;
36	      const url = new URL(req.originalUrl, baseUrl);
37	
38	      // Translate the Express actor to ActorContext | null. "none" → null.
39	      const expressActor = req.actor;
40	      let actor: ActorContext | null = null;
41	      if (expressActor?.type === "board") {
42	        actor = {
43	          type: "board",
44	          source: expressActor.source as ActorContext["source"],
45	          userId: expressActor.userId ?? "unknown",
46	          userName: (expressActor as { userName?: string | null }).userName ?? null,
47	          userEmail: (expressActor as { userEmail?: string | null }).userEmail ?? null,
48	          isInstanceAdmin: Boolean((expressActor as { isInstanceAdmin?: boolean }).isInstanceAdmin),
49	          companyIds: (expressActor as { companyIds?: string[] }).companyIds,
50	          memberships: (expressActor as { memberships?: ActorMembership[] }).memberships,
51	          keyId: (expressActor as { keyId?: string }).keyId,
52	          runId: expressActor.runId,
53	        };
54	      } else if (expressActor?.type === "agent") {
55	        actor = {
56	          type: "agent",
57	          source: expressActor.source as ActorContext["source"],
58	          agentId: expressActor.agentId ?? "unknown",
59	          companyId: expressActor.companyId ?? "",
60	          keyId: (expressActor as { keyId?: string }).keyId,
61	          runId: expressActor.runId,
62	        };
63	      }
64	
65	      // Build the Web-API-compatible Headers object from Express's incoming
66	      // headers map. Express lowercases all header names, so this is safe.
67	      const headers = new Headers();
68	      for (const [name, value] of Object.entries(req.headers)) {
69	        if (value === undefined) continue;
70	        if (Array.isArray(value)) {
71	          for (const v of value) headers.append(name, v);
72	        } else {
73	          // value is string here; cast required because Object.entries loses
74	          // the discriminated IncomingHttpHeaders union.
75	          headers.set(name, value as string);
76	        }
77	      }
78	
79	      const ctx: RequestCtx = {
80	        method: req.method,
81	        url,
82	        headers,
83	
84	        // Body is already parsed by express.json() — just return the cached
85	        // object rather than re-serialising/re-parsing it.
86	        json<T = unknown>(): Promise<T> {
87	          return Promise.resolve(req.body as T);
88	        },
89	        text(): Promise<string> {
90	          if (typeof req.body === "string") return Promise.resolve(req.body);
91	          return Promise.resolve(JSON.stringify(req.body));
92	        },
93	
94	        param(name: string): string | undefined {
95	          const value = req.params[name];
96	          return value === undefined ? undefined : String(value);
97	        },
98	        query(name: string): string | undefined {
99	          const value = req.query[name];
100	          if (value === undefined) return undefined;
101	          // Express query values can be string | ParsedQs | string[] | ParsedQs[]
102	          // We only surface the first scalar string.
103	          if (typeof value === "string") return value;
104	          if (Array.isArray(value)) {
105	            const first = value[0];
106	            return typeof first === "string" ? first : undefined;
107	          }
108	          return undefined;
109	        },
110	
111	        actor,
112	        db: deps.db,
113	        storage: deps.storage,
114	      };
115	
116	      const response = await handler(ctx);
117	
118	      res.status(response.status);
119	
120	      // Forward response headers (skip ones Express manages itself).
121	      response.headers.forEach((value, name) => {
122	        const lower = name.toLowerCase();
123	        if (lower === "transfer-encoding" || lower === "content-length") return;
124	        res.setHeader(name, value);
125	      });
126	
127	      const body = await response.text();
128	      res.send(body);
129	    } catch (err) {
130	      next(err);
131	    }
132	  };
133	  (wrapper as TaggedHandler).__handler = handler;
134	  return wrapper as TaggedHandler;
135	}
